--
-- Estrutura para tabela `sprints`
--

CREATE TABLE `sprints` (
  `id` int NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `goal` text COLLATE utf8mb4_unicode_ci,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `status` enum('Planejada','Ativa','Concluída','Cancelada') COLLATE utf8mb4_unicode_ci DEFAULT 'Planejada',
  `created_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estrutura para tabela `surveys`
--

CREATE TABLE `surveys` (
  `id` int NOT NULL,
  `title` varchar(300) NOT NULL,
  `description` text,
  `type` enum('single','multiple','rating') DEFAULT 'single',
  `active` tinyint(1) DEFAULT '1',
  `anonymous` tinyint(1) DEFAULT '0',
  `created_by` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Estrutura para tabela `survey_options`
--

CREATE TABLE `survey_options` (
  `id` int NOT NULL,
  `survey_id` int NOT NULL,
  `label` varchar(300) NOT NULL,
  `sort_order` int DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Estrutura para tabela `survey_votes`
--

CREATE TABLE `survey_votes` (
  `id` int NOT NULL,
